window.VOCAB_LWS_META = [{"batch":2,"added":"2026-11-07","lesson":1,"lesson_title":"Glück im Alltag","book":"Schritte plus Neu 5 · Lernwortschatz","pages":"LWS 171–175","tips":[{"text":"Das Wort *als* hat mehrere Bedeutungen. Schreiben Sie zu jeder Bedeutung einen Satz.","text_en":"*als* 这个词有好几个意思。请为每个意思各写一个句子。","example":"Wann? Als ich drei Jahre alt war, bekam ich mein erstes Haustier.","answer":["Vergleich: Jan ist älter als Julian","Berufsbezeichnung: Er arbeitet als Arzt"],"note":"三个意思：*als* = 当……的时候（过去发生的一次性事件，动词放在句末）；*als* 用在比较级后面 = 比；*als* + 职业或角色 = 作为。如果是过去反复发生的事，要用 *wenn*，不用 *als*。"}],"count":78},{"batch":3,"added":"2026-11-07","lesson":2,"lesson_title":"Unterhaltung","book":"Schritte plus Neu 5 · Lernwortschatz","pages":"LWS 175–179","tips":[{"text":"Schreiben Sie eine kleine Geschichte mit den Wörtern aus der Lektion.","text_en":"用这一课的词写一个小故事。","example":"Meine Geschichte handelt von einem unglaublichen Abenteuer: Ich begegnete in einer grossen Stadt dem Star aus meiner Lieblingsserie. Unglaublich! Ich war optimistisch, dass …","answer":["… ich ein Foto mit ihm machen kann. Ich hatte zwar nicht den Mut, ihn anzusprechen, aber dann kam die grosse Überraschung: Er fragte mich, wo der Bahnhof ist!"],"note":"这是参考答案，你写的可以很不一样。中文意思：“……我还能和他合影。我虽然没有勇气跟他说话，但接着大惊喜就来了：他问我火车站在哪里！”这里用到了 Lektion 1（第 1 课）的 *zwar … aber*、*der Mut* 和 *die Überraschung*。"}],"count":66},{"batch":4,"added":"2026-11-07","lesson":3,"lesson_title":"Gesund bleiben","book":"Schritte plus Neu 5 · Lernwortschatz","pages":"LWS 179–183","tips":[{"text":"Lernen Sie typische Wendungen zusammen.","text_en":"把常见的固定搭配放在一起学。","example":"den Blutdruck messen, Blut abnehmen, das Gewicht prüfen, den Bauch …","answer":["den Bauch untersuchen","jemanden impfen","Medikamente verschreiben","jemanden krankschreiben","ein Gespräch führen","einen Termin vereinbaren","Sport treiben","auf Schokolade verzichten"],"note":"*den Bauch untersuchen* 补全了课本上的列表（检查腹部）。其他都是本课里值得当作一个整体来学的词组：打疫苗、开药、给某人开病假证明、进行谈话、预约、做运动、戒掉巧克力。"}],"count":68},{"batch":1,"added":"2026-11-06","lesson":4,"lesson_title":"Sprachen","book":"Schritte plus Neu 5 · Lernwortschatz","pages":"LWS 184–187","tips":[{"text":"Im Deutschen enden viele Sprachen auf «-isch». Schreiben Sie.","text_en":"在德语里，很多语言的名称以 «-isch» 结尾。请写一写。","example":"Griechisch, Französisch, …","answer":["Englisch","Spanisch","Italienisch","Portugiesisch","Russisch","Polnisch","Türkisch","Arabisch","Chinesisch","Japanisch","Ungarisch","Albanisch"],"note":"语言名称是中性名词，通常不加冠词：*Ich lerne Spanisch.*（我学西班牙语。）并不是所有语言都以 *-isch* 结尾：*Deutsch*、*Hindi* 和 *Swahili* 就不是。"}],"count":60},{"batch":5,"added":"2026-11-09","lesson":5,"lesson_title":"Eine Arbeit finden","book":"Schritte plus Neu 5 · Lernwortschatz","pages":"LWS 188–191","tips":[{"text":"Notieren Sie einen Beruf. Bilden Sie mit seinen Buchstaben einen Satz.","text_en":"写下一个职业。用它的字母组成一个句子。","example":"Maler: *M*ein *A*rzt *l*iest *e*inen *R*eiseführer.","answer":["Arzt: Anna ruft zwei Taxis","Lehrer: Lara erklärt heute Ronja einen Roman"],"note":"每个词都以这个职业名称里的下一个字母开头。只要句子说得通，就算对。"}],"count":53},{"batch":6,"added":"2026-11-09","lesson":6,"lesson_title":"Dienstleistung","book":"Schritte plus Neu 5 · Lernwortschatz","pages":"LWS 191–195","tips":[{"text":"Bilden Sie mit den Buchstaben von einem langen Wort neue Wörter.","text_en":"用一个长单词里的字母组成新单词。","example":"Bedienungsanleitung: laut, Dienstag, Tal, …","answer":["Bad","Geld","Insel","Nadel","Lied","Sieg","Tanne","Leben"],"note":"每个字母的使用次数不能超过它在 *Bedienungsanleitung* 里出现的次数。"}],"count":66},{"batch":7,"added":"2026-11-09","lesson":7,"lesson_title":"Rund ums Wohnen","book":"Schritte plus Neu 5 · Lernwortschatz","pages":"LWS 196–200","tips":[{"text":"Leiten Sie unbekannte Wörter von bekannten Wörtern ab.","text_en":"从认识的词推导出不认识的词。","example":"unaufmerksam = nicht aufmerksam","answer":["unverständlich = nicht verständlich","ungemütlich = nicht gemütlich","friedlich = ohne Streit, voller Frieden","der Stadtrand = der Rand der Stadt","das Fernsehverbot = das Verbot, fernzusehen"],"note":"*un-* 把形容词变成反义词；复合名词的基本意思由最后一个部分决定。"}],"count":67}];
